177	void AsynchronousInsertQueue::push(ASTPtr query, ContextPtr query_context)
178	{
179	    query = query->clone();
180	    const auto & settings = query_context->getSettingsRef();
181	    auto & insert_query = query->as<ASTInsertQuery &>();
182	
183	    InterpreterInsertQuery interpreter(query, query_context, settings.insert_allow_materialized_columns);
184	    auto table = interpreter.getTable(insert_query);
185	    auto sample_block = interpreter.getSampleBlock(insert_query, table, table->getInMemoryMetadataPtr());
186	
187	    if (!FormatFactory::instance().isInputFormat(insert_query.format))
188	        throw Exception(ErrorCodes::UNKNOWN_FORMAT, "Unknown input format {}", insert_query.format);
189	
190	    /// For table functions we check access while executing
191	    /// InterpreterInsertQuery::getTable() -> ITableFunction::execute().
192	    if (insert_query.table_id)
193	        query_context->checkAccess(AccessType::INSERT, insert_query.table_id, sample_block.getNames());
194	
195	    String bytes;
196	    {
197	        auto read_buf = getReadBufferFromASTInsertQuery(query);
198	        WriteBufferFromString write_buf(bytes);
199	        copyData(*read_buf, write_buf);
200	    }
201	
202	    if (auto quota = query_context->getQuota())
203	        quota->used(QuotaType::WRITTEN_BYTES, bytes.size());
204	
205	    auto entry = std::make_shared<InsertData::Entry>(std::move(bytes), query_context->getCurrentQueryId());
206	    InsertQuery key{query, settings};
207	
208	    {
209	        /// Firstly try to get entry from queue without exclusive lock.
210	        std::shared_lock read_lock(rwlock);
211	        if (auto it = queue.find(key); it != queue.end())
212	        {
213	            pushImpl(std::move(entry), it);
214	            return;
215	        }
216	    }
217	
218	    std::lock_guard write_lock(rwlock);
219	    auto it = queue.emplace(key, std::make_shared<Container>()).first;
220	    pushImpl(std::move(entry), it);
221	}
