253	void AsynchronousInsertQueue::waitForProcessingQuery(const String & query_id, const Milliseconds & timeout)
254	{
255	    InsertData::EntryPtr entry;
256	
257	    {
258	        std::lock_guard lock(currently_processing_mutex);
259	        auto it = currently_processing_queries.find(query_id);
260	        if (it == currently_processing_queries.end())
261	            return;
262	
263	        entry = it->second;
264	    }
265	
266	    bool finished = entry->wait(timeout);
267	
268	    if (!finished)
269	        throw Exception(ErrorCodes::TIMEOUT_EXCEEDED, "Wait for async insert timeout ({} ms) exceeded)", timeout.count());
270	
271	    if (auto exception = entry->getException())
272	        std::rethrow_exception(exception);
273	}
