275	void AsynchronousInsertQueue::busyCheck()
276	{
277	    auto timeout = busy_timeout;
278	
279	    while (!shutdown)
280	    {
281	        std::this_thread::sleep_for(timeout);
282	
283	        /// TODO: use priority queue instead of raw unsorted queue.
284	        timeout = busy_timeout;
285	        std::shared_lock read_lock(rwlock);
286	
287	        for (auto & [key, elem] : queue)
288	        {
289	            std::lock_guard data_lock(elem->mutex);
290	            if (!elem->data)
291	                continue;
292	
293	            auto lag = std::chrono::steady_clock::now() - elem->data->first_update;
294	            if (lag >= busy_timeout)
295	                scheduleDataProcessingJob(key, std::move(elem->data), getContext());
296	            else
297	                timeout = std::min(timeout, std::chrono::ceil<std::chrono::milliseconds>(busy_timeout - lag));
298	        }
299	    }
300	}
301	
302	void AsynchronousInsertQueue::staleCheck()
303	{
304	    while (!shutdown)
305	    {
306	        std::this_thread::sleep_for(stale_timeout);
307	        std::shared_lock read_lock(rwlock);
308	
309	        for (auto & [key, elem] : queue)
310	        {
311	            std::lock_guard data_lock(elem->mutex);
312	            if (!elem->data)
313	                continue;
314	
315	            auto lag = std::chrono::steady_clock::now() - elem->data->last_update;
316	            if (lag >= stale_timeout)
317	                scheduleDataProcessingJob(key, std::move(elem->data), getContext());
318	        }
319	    }
320	}
