322	void AsynchronousInsertQueue::cleanup()
323	{
324	    /// Do not run cleanup too often,
325	    /// because it holds exclusive lock.
326	    auto timeout = busy_timeout * 5;
327	
328	    while (!shutdown)
329	    {
330	        std::this_thread::sleep_for(timeout);
331	        std::vector<InsertQuery> keys_to_remove;
332	
333	        {
334	            std::shared_lock read_lock(rwlock);
335	
336	            for (auto & [key, elem] : queue)
337	            {
338	                std::lock_guard data_lock(elem->mutex);
339	                if (!elem->data)
340	                    keys_to_remove.push_back(key);
341	            }
342	        }
343	
344	        if (!keys_to_remove.empty())
345	        {
346	            std::lock_guard write_lock(rwlock);
347	            size_t total_removed = 0;
348	
349	            for (const auto & key : keys_to_remove)
350	            {
351	                auto it = queue.find(key);
352	                if (it != queue.end() && !it->second->data)
353	                {
354	                    queue.erase(it);
355	                    ++total_removed;
356	                }
357	            }
358	
359	            if (total_removed)
360	                LOG_TRACE(log, "Removed stale entries for {} queries from asynchronous insertion queue", total_removed);
361	        }
362	
363	        {
364	            std::vector<String> ids_to_remove;
365	            std::lock_guard lock(currently_processing_mutex);
366	
367	            for (const auto & [query_id, entry] : currently_processing_queries)
368	                if (entry->isFinished())
369	                    ids_to_remove.push_back(query_id);
370	
371	            if (!ids_to_remove.empty())
372	            {
373	                for (const auto & id : ids_to_remove)
374	                    currently_processing_queries.erase(id);
375	
376	                LOG_TRACE(log, "Removed {} finished entries from asynchronous insertion queue", ids_to_remove.size());
377	            }
378	        }
379	    }
380	}
